/* Object-first strategy controls; all paid mutations still use the authoritative APIs. */
const gameSections=[['plant','🌱','Посадить'],['grow','💧','Ухаживать'],['build','🛠️','Улучшить'],['harvest','🧺','Собрать'],['camera','📹','Посмотреть']];
function gameOpenBed(id,section){closeFieldMenu();if(section==='plant'){gamePlant(id);return}openFarmBed(id,section)}
farmObjectMenu=function(){modalForm('Что появится здесь?',`<div class="game-build-grid"><button type="button" class="game-build-card" onclick="modal.close();rentalCity=selectedFarmCity();location.hash='choose-bed';render()"><span>🌱</span><b>Грядка</b><small>1 × 3 м или 1 × 7 м</small><em>Выбрать размер →</em></button>${[['🐔','Курятник'],['🐇','Крольчатник'],['🐄','Коровник']].map(([icon,name])=>`<button type="button" class="game-build-card soon" disabled><span>${icon}</span><b>${name}</b><small>Скоро</small></button>`).join('')}</div><p class="note">Участок в текущем городе. Цена и срок аренды — на следующем шаге.</p>`,()=>{})};
function gameWork(p){return (opsData?.orders||[]).find(o=>o.plot_id===p.id&&!['done','cancelled'].includes(o.status))}
function gameLead(p){const o=gameWork(p);if(o)return {icon:['working','on_way'].includes(o.status)?'👩‍🌾':'🕒',title:o.status==='working'?'Садовник работает':o.status==='on_way'?'Садовник идёт к грядке':'Работа запланирована',text:o.title,tab:'activity'};if(p.growing_state==='harvest_ready')return {icon:'🧺',title:'Пора собирать урожай',text:'Выберите назначение корзины',tab:'harvest'};if(['ready','empty','finished','unchecked'].includes(p.growing_state))return {icon:'🌱',title:'Выберите, что посадить',text:p.growing_state==='ready'?'Грядка подготовлена':'Сначала согласуем план и подготовку',tab:'plant'};return {icon:'🌿',title:'Посадки растут',text:'Уход по плану садовника',tab:'grow'}}
farmBedMenu=function(id){const p=myPlots().find(x=>x.id===id);if(!p)return;closeFieldMenu();const lead=gameLead(p),scene=typeof demoGardenScene==='function'?demoGardenScene(p):null;const panel=document.createElement('section');panel.className='field-menu strategy-menu';panel.dataset.plot=id;panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Действия с грядкой '+p.name);panel.innerHTML=`<div class="field-menu-head"><div><small>ГРЯДКА №${p.id} · ${p.size} М²</small><h2>${esc(p.name)}</h2></div><button class="field-close" aria-label="Закрыть действия" onclick="closeFieldMenu(true)">×</button></div>${scene?`<p class="strategy-demo">Деморисунок: ${esc(scene.crop)} · ${demoGardenLabel(scene)}. Действия ниже учитывают подтверждённое состояние участка.</p>`:''}<button class="strategy-lead" onclick="gameOpenBed(${id},'${lead.tab}')"><span>${lead.icon}</span><div><b>${esc(lead.title)}</b><small>${esc(lead.text||'')}</small></div><em>→</em></button><div class="strategy-actions">${gameSections.map(([tab,icon,title])=>`<button onclick="gameOpenBed(${id},'${tab}')"><span>${icon}</span><b>${title}</b></button>`).join('')}</div><button class="strategy-history" onclick="gameOpenBed(${id},'activity')">📋 Ход работ и расходы</button>`;document.body.append(panel);panel.querySelector('.field-close').focus()};
let gamePlantPlot=null;
async function gamePlant(id){const p=myPlots().find(x=>x.id===id);if(!p)return;gamePlantPlot=id;closeFieldMenu();try{const userId=account.id;const data=await api('season');if(account?.id!==userId)return;seasonData=data;gamePlantView(id)}catch(e){toast(e.message)}}
function gamePlantView(id,shop=false){const p=myPlots().find(x=>x.id===id);if(!p)return;const supplies=(seasonData?.supplies||[]).filter(s=>Number(s.balance)>Number(s.reserved||0)&&(!s.expires_on||String(s.expires_on).slice(0,10)>=new Date().toISOString().slice(0,10))&&demoCatalog.some(c=>c.id===s.catalog_id&&['Семена','Рассада'].includes(c.category)));const showShop=shop||!supplies.length;const planted=['planted','growing','harvest_ready'].includes(p.growing_state),work=gameWork(p),service=opsData?.services.find(s=>s.code==='plant');modalForm('🌱 Что посадим · грядка №'+id,`<div class="game-steps"><b>1. Выбрать</b><span>2. Согласовать</span><span>3. Посадить</span></div>${planted?'<p class="game-warning">На грядке уже есть посадки. Для новой культуры нужна свободная зона и согласованный план.</p>':''}${work?'<p class="game-warning">Есть незавершённая работа. Новая посадка дождётся её завершения.</p>':''}<div class="actions"><button type="button" class="btn ${showShop?'light':''}" onclick="gamePlantView(${id},false)">Мои семена · ${supplies.length}</button><button type="button" class="btn ${showShop?'':'light'}" onclick="gamePlantView(${id},true)">Магазин семян</button></div>${showShop?`<p>После покупки семена появятся в запасах, когда ферма подтвердит получение.</p><div class="game-seeds">${demoCatalog.filter(c=>c.category==='Семена').slice(0,24).map(c=>`<button type="button" onclick="gameSeedBuy(${id},'${c.id}')"><span>🌱</span><b>${esc(c.name)}</b><small>${c.price} демо-₽ / ${esc(c.unit)}</small></button>`).join('')}</div>`:`<div class="game-seeds">${supplies.map(s=>`<button type="button" onclick="gameSeedUse(${id},'${s.id}')"><span>🌱</span><b>${esc(s.name)}</b><small>Свободно ${Number(s.balance)-Number(s.reserved||0)} ${esc(s.unit)}</small></button>`).join('')}</div>`}<p class="note">Посадка: ${service?money(service.price_kopecks)+' · примерно '+service.duration_minutes+' мин.':'цену подтвердит ферма'}. Семена и подготовка оплачиваются отдельно. Количество растений и совместимость утверждает садовник.</p><div class="actions"><button type="button" class="btn light" onclick="modal.close();lifeRequest('seedlings',${id})">🪴 Хочу рассаду</button><button type="button" class="btn light" onclick="modal.close();lifeRequest('kit',${id})">🥗 Подобрать набор и план</button></div>`,()=>{})}
function gameSeedBuy(plot,id){const item=demoCatalog.find(c=>c.id===id&&c.category==='Семена');if(!item)return;const key=crypto.randomUUID();formAsync('Семена для грядки №'+plot,`<h3>${esc(item.name)}</h3><label>Упаковок<input name="qty" type="number" min="1" max="99" step="1" value="1" required oninput="document.getElementById('seed-total').textContent=money(${item.price*100}*Number(this.value))"></label><p>Семена: <b id="seed-total">${money(item.price*100)}</b></p><p>Получение на грядке №${plot}. Посадка не включена. После приёмки откройте «Посадить → Мои семена».</p><button class="btn">Купить демобалансом</button>`,async f=>{await api('market-checkout',{key,delivery:'На грядку — имитация',plot,items:[{id,qty:Number(f.get('qty'))}]});walletData=null;toast('Семена заказаны. Ожидаем подтверждения получения.')})}
async function gameSeedUse(plot,supply){const key=crypto.randomUUID();const p=myPlots().find(p=>p.id===plot),s=seasonData?.supplies.find(s=>s.id===supply);if(!p||!s)return;const plan=opsData?.plans.find(x=>x.plot_id===plot);if(p.growing_state!=='ready'||!plan||gameWork(p)){formAsync('Подготовим посадку',`<h3>${esc(s.name)} · грядка №${plot}</h3><p>${gameWork(p)?'Сначала нужно завершить текущую работу.':p.growing_state==='ready'?'Нужно согласовать план культуры.':'Садовник проверит свободное место и необходимость подготовки.'}</p><p>Семена не расходуются. Итоговая стоимость и сроки потребуют вашего подтверждения.</p><label>Пожелания<textarea name="details" required minlength="5">Хочу посадить ${esc(s.name)} из моих запасов. Подтвердите план, количество и подготовку.</textarea></label><button class="btn">Отправить пожелание садовнику</button>`,async f=>lifeAction('request',{key,plot,kind:'kit',details:f.get('details')}));return}modal.close();await roomOrder(plot,'plant');const select=document.querySelector('#fields select[name=supply]');if(select)select.value=supply}
function gameEarlyHarvest(id){const p=myPlots().find(p=>p.id===id);if(!p)return;if(!['planted','growing'].includes(p.growing_state)){toast('На грядке пока нет подтверждённых растущих посадок');return}const key=crypto.randomUUID();formAsync('Запросить ранний сбор',`<p>Урожай ещё не подтверждён как созревший. Садовник оценит возможность сбора и объяснит, как это повлияет на количество и спелость.</p><label>Для чего нужен ранний сбор?<textarea name="details" minlength="5" required></textarea></label><p>Сейчас нет оплаты и команды на сбор.</p><button class="btn">Уточнить у садовника</button>`,async f=>lifeAction('request',{key,plot:id,kind:'ripeness',details:'Ранний сбор: '+f.get('details')}))}
farmViews.add(()=>{
 const add=document.querySelector('.add-parcel');if(add){add.setAttribute('aria-label','Добавить объект на свободном участке');add.querySelector('.parcel-sign')?.remove();add.querySelector('.parcel-status')?.remove()}
 const p=currentRoomPlot();if(!p)return;
 const tabs=document.querySelector('.room-tabs');if(tabs){tabs.insertAdjacentHTML('beforebegin',`<div class="strategy-room-nav">${gameSections.map(([tab,icon,title])=>`<button class="${plotRoomTab===tab?'selected':''}" onclick="gameOpenBed(${p.id},'${tab}')"><span>${icon}</span>${title}</button>`).join('')}<button onclick="openFarmBed(${p.id},'activity')">📋 История</button></div>`);tabs.hidden=true}
 const panel=document.querySelector('[role=tabpanel]');if(plotRoomTab==='grow'&&panel)panel.insertAdjacentHTML('afterbegin',`<section class="game-care-intro"><h2>💧 Забота по потребности растений</h2><p>Повторный заказ не ускоряет рост. Доступность учитывает состояние, план и текущие работы.</p><button class="btn" onclick="gamePlant(${p.id})">🌱 Выбрать посадки</button></section>`);
 if(plotRoomTab==='harvest'&&panel&&p.growing_state!=='harvest_ready')panel.insertAdjacentHTML('afterbegin',`<section class="game-warning"><h3>${['planted','growing'].includes(p.growing_state)?'Урожай ещё растёт':'Пока нечего собирать'}</h3><p>${['planted','growing'].includes(p.growing_state)?'Дата в плане — прогноз. Готовность подтвердит садовник.':'Сначала выберите культуру и согласуйте посадку.'}</p><button class="btn light" onclick="${['planted','growing'].includes(p.growing_state)?`gameEarlyHarvest(${p.id})`:`gamePlant(${p.id})`}">${['planted','growing'].includes(p.growing_state)?'Запросить ранний сбор':'Выбрать посадки'}</button></section>`);
 const work=gameWork(p);if(work){const hero=document.querySelector('.room-hero');hero?.insertAdjacentHTML('afterend',`<div class="game-work-state ${work.status==='working'?'is-working':''}"><span>${work.status==='working'?'👩‍🌾':'🕒'}</span><div><b>${work.status==='working'?'Садовник работает':'Работа ожидает следующего этапа'}</b><p>${esc(work.title)}</p></div><button class="btn light" onclick="openFarmBed(${p.id},'activity')">Подробнее</button></div>`)}
});
